$searchMime="From: Search sender <sucher@example.invalid>\r\nReply-To: sucher@example.invalid\r\nTo: mailbox@example.invalid\r\nSubject: =?UTF-8?B?".base64_encode('Grüße %_! search')."?=\r\nMessage-ID: <own-mail-search@example.invalid>\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n".str_repeat('Long original mail paragraph. ',1000).'SEARCH-BEYOND-EXCERPT';
$threadBatch=['uidvalidity'=>1,'messages'=>[['uid'=>8,'original'=>$searchMime]]];$threadBox->fetch();
$searchId=Db::run($db,'SELECT id FROM native_mailbox_messages WHERE club_id=? AND message_uid=8',[$threadClub])->fetchColumn();
$searchBefore=ownOriginalDatabaseHash($db,['native_mailbox_messages','native_mailbox_replies']);
foreach(['sucher@example.invalid','GRÜßE %_!','SEARCH-BEYOND-EXCERPT']as$term){$found=$threadBox->listing('active','all',1,$term);$check($found['total']===1&&$found['rows'][0]['id']===$searchId,'literal Unicode sender subject and complete bounded body search: '.$term);}
$found=$threadBox->listing('active','all',1,'Own manager conversation answer');$check($found['total']===1&&in_array($rootId,$found['rows'][0]['conversation_ids'],true),'search includes encrypted outgoing replies and retains one RFC conversation');
$check($threadBox->listing('active','mine',1,'SEARCH-BEYOND-EXCERPT')['total']===0&&$foreignBox->listing('all','all',1,'SEARCH-BEYOND-EXCERPT')['total']===0,'search applies responsibility and mailbox binding before decrypting candidate content');
$check($threadBox->listing('all','all',1,'%_!')['total']===1&&$threadBox->listing('all','all',1,'never-existing-search-text')['total']===0,'search treats SQL wildcard characters literally and returns a real empty state');
$check(ownOriginalDatabaseHash($db,['native_mailbox_messages','native_mailbox_replies'])===$searchBefore,'search never rewrites encrypted originals or creates a plaintext search index');
foreach([['bad'],str_repeat('x',201),"invalid\nquery",chr(255)]as$bad)$deny(fn()=>MailboxForm::query(['view'=>'messages','tab'=>'inbox','mailbox_q'=>$bad]),'invalid or unbounded mailbox search is rejected');
$searchQuery=['view'=>'messages','tab'=>'inbox','mailbox_q'=>'%_!'];$searchPage=new MailboxPage($db,'own-thread-board','own-csrf',$threadBox);$html=$searchPage->render($searchQuery);
$doc=new DOMDocument();@$doc->loadHTML($html);$xp=new DOMXPath($doc);$check($xp->query('//form[@role="search"]//input[@name="mailbox_q" and @type="search"]')->length===1&&$xp->query('//form[@role="search"]/ancestor::details')->length===0&&str_contains($html,'mailbox_q=%25_%21'),'search is visible outside advanced tools and remains in selected-message links');
$contextPost=['action'=>'mailbox-fetch','csrf'=>'own-csrf','mailbox_state'=>'active','mailbox_assigned'=>'all','mailbox_page'=>'1','mailbox_q'=>'changed'];$deny(fn()=>MailboxForm::command($searchQuery,$contextPost),'a stale form cannot silently replace the search selection');
$archived=$threadBox->change($searchId,1,'','archived');$originalBefore=$threadBox->get($searchId);$archiveView=$searchPage->render(['view'=>'messages','tab'=>'inbox','mailbox_state'=>'archived','mail'=>$searchId]);
$check(str_contains($archiveView,'id="mailbox-reply"')&&str_contains($archiveView,'data-mailbox-reply-jump'),'archive offers the real reply editor immediately without reopening or assigning');
$archiveDraft=$threadBox->saveReply($searchId,bin2hex(random_bytes(16)),0,'An answer directly from archive');$archiveSent=$threadBox->send($archiveDraft['id'],(int)$archiveDraft['version'],true);
$check($archiveSent['state']==='accepted'&&$threadBox->get($searchId)===$originalBefore&&$threadBox->original($searchId)===$searchMime&&$archiveSent['payload']['parent_id']==='<own-mail-search@example.invalid>','archived reply uses real reply semantics through a fake transport without changing source archive assignment version or bytes');
$deny(fn()=>(new Mailbox($db,'own-mail-other',$key))->saveReply($searchId,bin2hex(random_bytes(16)),0,'Not permitted'),'archived reply still rejects another club');
$threadBox->change($searchId,2,'','trashed');$deny(fn()=>$threadBox->saveReply($searchId,bin2hex(random_bytes(16)),0,'Trash cannot reply'),'trashed mail still cannot receive a new reply');
$trashView=$searchPage->render(['view'=>'messages','tab'=>'inbox','mailbox_state'=>'trashed','mail'=>$searchId]);$check(!str_contains($trashView,'id="mailbox-reply"'),'trash hides the reply editor and keeps restore as the available action');
$threadBox->change($searchId,3,'','active');

// The accepted original can predate this renderer: viewing never rewrites its encrypted envelope.
$unicodeExistingText='äöü ÄÖÜ ß ẞ € 🎶';
$unicodeExistingHtml='<html><head><meta http-equiv="Content-Type" content="text/html; charset=windows-1252"></head><body><p id="old-mail-unicode">äöü ÄÖÜ ß &#7838; € &#127926;</p></body></html>';
$unicodeExistingRaw="From: sender@example.invalid\r\nTo: mailbox@example.invalid\r\nSubject: =?UTF-8?B?".base64_encode($unicodeExistingText)."?=\r\nMessage-ID: <own-existing-unicode@example.invalid>\r\nContent-Type: multipart/alternative; boundary=own-existing-unicode\r\n\r\n--own-existing-unicode\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: quoted-printable\r\n\r\n".quoted_printable_encode($unicodeExistingText)."\r\n--own-existing-unicode\r\nContent-Type: text/html; charset=windows-1252\r\nContent-Transfer-Encoding: quoted-printable\r\n\r\n".quoted_printable_encode(mb_convert_encoding($unicodeExistingHtml,'Windows-1252','UTF-8'))."\r\n--own-existing-unicode--\r\n";
$threadBatch=['uidvalidity'=>1,'messages'=>[['uid'=>9,'original'=>$unicodeExistingRaw]]];$threadBox->fetch();
$unicodeExistingId=Db::run($db,'SELECT id FROM native_mailbox_messages WHERE club_id=? AND message_uid=9',[$threadClub])->fetchColumn();$unicodeBefore=$threadBox->get($unicodeExistingId);$unicodeRowsBefore=ownOriginalDatabaseHash($db,['native_mailbox_messages','native_mailbox_replies','native_private_settings']);
$unicodeVisible=$threadBox->formatted($unicodeExistingId);$unicodeDom=new DOMDocument();@$unicodeDom->loadHTML($unicodeVisible,LIBXML_NONET);$unicodeNode=(new DOMXPath($unicodeDom))->query('//*[@id="old-mail-unicode"]')->item(0);
$check($unicodeNode?->textContent===$unicodeExistingText&&trim($unicodeBefore['envelope']['text'])===$unicodeExistingText,'an existing encrypted legacy-charset original displays the same correct Unicode as its earlier plain-text projection');
$check($threadBox->get($unicodeExistingId)===$unicodeBefore&&$threadBox->original($unicodeExistingId)===$unicodeExistingRaw&&ownOriginalDatabaseHash($db,['native_mailbox_messages','native_mailbox_replies','native_private_settings'])===$unicodeRowsBefore,'correcting the read-time HTML charset changes no original bytes encrypted envelope revision reply or private cursor');
$unicodeAnswer=$threadBox->saveReply($unicodeExistingId,bin2hex(random_bytes(16)),0,$unicodeExistingText,'<p>'.$unicodeExistingText.'</p>');$unicodeAccepted=$threadBox->send($unicodeAnswer['id'],(int)$unicodeAnswer['version'],true);$unicodeReplyRaw=$threadWire->toString();$unicodeReplyEnvelope=\Kulturhus\Native\Communication\Mail\Mime::mailbox($unicodeReplyRaw);
$check($unicodeAccepted['state']==='accepted'&&str_contains($unicodeReplyEnvelope['text'],$unicodeExistingText)&&str_contains($unicodeReplyEnvelope['text'],'> '.$unicodeExistingText)&&$threadBox->get($unicodeExistingId)===$unicodeBefore&&$unicodeReplyEnvelope['thread_references']===['<own-existing-unicode@example.invalid>'],'the existing-mail fake transport preserves authored and quoted Unicode with the same RFC conversation and immutable source');
